#!/usr/bin/env python3
"""Writes the shell completion scripts into a C++ header, so `forti completion SHELL` prints exactly
the files that are installed.

    embed.py OUTPUT NAME=SCRIPT...    (meson runs it; see src/cli/meson.build)
"""

import sys

DELIMITER = "forti_completion"


def main() -> int:
    output, *pairs = sys.argv[1:]
    lines = [
        "// Generated by completions/embed.py from the scripts in completions/. Do not edit.",
        "#pragma once",
        "#include <string_view>",
        "namespace forti::cli::completion_scripts {",
    ]
    for pair in pairs:
        name, path = pair.split("=", 1)
        with open(path, encoding="utf-8") as file:
            text = file.read()
        if f"){DELIMITER}\"" in text:
            sys.exit(f"{path}: contains the raw string delimiter")
        lines.append(f'    inline constexpr std::string_view {name} = R"{DELIMITER}({text}){DELIMITER}";')
    lines.append("}")
    with open(output, "w", encoding="utf-8") as file:
        file.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
